public async Task<Resultado> ArquivarDocumento(string documentoId, string usuarioId)
{
    var documento = await _documentos.Find(d => d.Id == documentoId).FirstOrDefaultAsync();

    if (documento != null)
    {
        if (documento.DonoId == usuarioId)
        {
            if (!documento.Arquivado)
            {
                await ArquivarNoBanco(documentoId);
                return Resultado.Ok("Documento arquivado");
            }
            else
            {
                return Resultado.Falha("Documento já está arquivado");
            }
        }
        else
        {
            return Resultado.Falha("Só o dono pode arquivar");
        }
    }
    else
    {
        return Resultado.Falha("Documento não encontrado");
    }
}

